"""D02 offline producer. Python standard library only. Run: python producer.py."""
from pathlib import Path
from itertools import permutations
import json, hashlib

HERE = Path(__file__).resolve().parent
SOURCE = json.loads((HERE / 'source-data.json').read_text(encoding='utf-8-sig'))
TENANTS = SOURCE['tenants']; UNITS = SOURCE['units']
PAIRS = {(p['tenant_id'], p['unit_id']): p for p in SOURCE['pair_estimates']}
def reasons(t, u):
    return ([f"面积 {u['area_sqm']} m² < 所需 {t['min_area_sqm']} m²"] if u['area_sqm'] < t['min_area_sqm'] else []) + [f"缺少 {x}" for x in t['required_features'] if x not in u['features']]
def valid(a):
    if any(reasons(t, UNITS[a[i]]) for i,t in enumerate(TENANTS)): return False
    for rule in SOURCE['separation_rules']:
        x = next(i for i,t in enumerate(TENANTS) if t['tenant_id']==rule['tenant_a'])
        y = next(i for i,t in enumerate(TENANTS) if t['tenant_id']==rule['tenant_b'])
        if abs(UNITS[a[x]]['corridor_position']-UNITS[a[y]]['corridor_position']) < rule['minimum_position_gap']: return False
    return True
assignments = [a for a in permutations(range(len(UNITS)), len(TENANTS)) if valid(a)]
# Independent recursive construction with local pruning, then set equality.
def build(part=()):
    if len(part)==len(TENANTS):
        yield part; return
    i=len(part)
    for u in range(len(UNITS)):
        if u in part or reasons(TENANTS[i], UNITS[u]): continue
        trial=part+(u,)
        ok=True
        for r in SOURCE['separation_rules']:
            ia=int(r['tenant_a'][1:]); ib=int(r['tenant_b'][1:])
            if ia<len(trial) and ib<len(trial) and abs(UNITS[trial[ia]]['corridor_position']-UNITS[trial[ib]]['corridor_position'])<r['minimum_position_gap']: ok=False
        if ok: yield from build(trial)
assert set(assignments)==set(build())
rows=[]
for a in assignments:
    p=[PAIRS[(t['tenant_id'], UNITS[a[i]]['unit_id'])] for i,t in enumerate(TENANTS)]
    ranks=[x['preference_rank'] for x in p]
    rows.append(dict(id='-'.join(map(str,a)), units=a, ranks=ranks, worst=max(ranks), rank_sum=sum(ranks), base=sum(x['base_contribution'] for x in p), busy=sum(x['busyday_contribution'] for x in p)))
solutions={}
for scenario in ['base','busy']:
    revenue=max(rows,key=lambda r:r[scenario])
    fair=min(rows,key=lambda r:(r['worst'],r['rank_sum'],-r[scenario]))
    frontier=[]
    for cap in range(1,8):
        eligible=[r for r in rows if r['worst']<=cap]
        frontier.append(dict(cap=cap, solution=max(eligible,key=lambda r:r[scenario]) if eligible else None))
    solutions[scenario]=dict(contribution=revenue,fairness=fair,frontier=frontier, sacrifice=revenue[scenario]-fair[scenario])
computed=dict(dataset_id='D02', synthetic=True, assignments=rows, solutions=solutions, pair_constraints=[dict(tenant=t['tenant_id'],unit=u['unit_id'],reasons=reasons(t,u)) for t in TENANTS for u in UNITS], verification=dict(permutation_vs_pruned_recursion=True, feasible_count=len(rows)), definitions=dict(contribution='LC最小单位；六家配对之和',worst='六家志愿名次的最大值；越小越好',fairness=SOURCE['fairness_order']))
(HERE/'computed.json').write_text(json.dumps(computed,ensure_ascii=False,indent=2),encoding='utf-8', newline='\n')
MOTION=(HERE/'motion-runtime.js').read_text(encoding='utf-8')
